  // webgl.ts — PBR WebGL2 rendering backend for GoSX Scene3D.
  // @ts-check
  //
  // Provides Cook-Torrance BRDF with per-pixel lighting, replacing
  // the legacy vertex-color renderer for WebGL2-capable browsers.
  //
  // This file ships as the lazily fetched bootstrap-feature-scene3d-webgl.js
  // chunk. A WebGPU-capable browser never runs it, so it must not load until
  // the mount path picks WebGL, or until a WebGPU device loss forces the
  // fallback ladder down to WebGL. See 26j-feature-scene3d-webgl-prefix.js
  // for the symbols the base chunk bridges in, and 16c-scene-shared-pbr.ts
  // for the backend-agnostic helpers that stayed eager.

  /**
   * @typedef {object} GoSXSceneWebGLRenderer
   * @property {(bundle: object, frame?: number) => void} render
   * @property {() => void} dispose
   */

  // --- PBR Shader Sources ---

  function scenePBRSRGBChannelToLinear(value) {
    var channel = Math.max(0, Math.min(1, sceneNumber(value, 0)));
    return channel <= 0.04045
      ? channel / 12.92
      : Math.pow((channel + 0.055) / 1.055, 2.4);
  }

  const SCENE_PBR_VERTEX_SOURCE = [
    "#version 300 es",
    "precision highp float;",
    "precision highp int;",
    "",
    "in vec3 a_position;",
    "in vec3 a_normal;",
    "in vec2 a_uv;",
    "in vec4 a_tangent;",
    "",
    "uniform mat4 u_viewMatrix;",
    "uniform mat4 u_projectionMatrix;",
    "uniform mat4 u_modelMatrix;",
    "uniform vec3 u_modelScaleSigns;",
    "",
    "out vec3 v_worldPosition;",
    "out vec3 v_normal;",
    "out vec2 v_uv;",
    "out vec3 v_tangent;",
    "out vec3 v_bitangent;",
    "flat out vec4 v_instanceColor;",
    "",
    "void gosxApplyCustomVertex(inout vec3 position, inout vec3 normal, inout vec2 uv) {}",
    "",
    "void main() {",
    "    vec3 gosxPosition = a_position;",
    "    vec3 gosxNormal = a_normal;",
    "    vec2 gosxUV = a_uv;",
    "    gosxApplyCustomVertex(gosxPosition, gosxNormal, gosxUV);",
    "    vec4 gosxWorldPosition = u_modelMatrix * vec4(gosxPosition, 1.0);",
    "    mat3 gosxModelBasis = mat3(",
    "        normalize(u_modelMatrix[0].xyz) * u_modelScaleSigns.x,",
    "        normalize(u_modelMatrix[1].xyz) * u_modelScaleSigns.y,",
    "        normalize(u_modelMatrix[2].xyz) * u_modelScaleSigns.z",
    "    );",
    "    v_worldPosition = gosxWorldPosition.xyz;",
    "    v_normal = normalize(gosxModelBasis * gosxNormal);",
    "    v_uv = gosxUV;",
    "",
    "    vec3 T = normalize(gosxModelBasis * a_tangent.xyz);",
    "    vec3 N = v_normal;",
    "    vec3 B = cross(N, T) * a_tangent.w;",
    "    v_tangent = T;",
    "    v_bitangent = B;",
    "    v_instanceColor = vec4(1.0);",
    "",
    "    gl_Position = u_projectionMatrix * u_viewMatrix * gosxWorldPosition;",
    "}",
  ].join("\n");

