    "#version 300 es",
    "precision highp float;",
    "precision highp int;",
    "#define GOSX_HDR_IBL 1",
    "",
    "in vec3 v_worldPosition;",
    "in vec3 v_normal;",
    "in vec2 v_uv;",
    "in vec3 v_tangent;",
    "in vec3 v_bitangent;",
    "flat in vec4 v_instanceColor;",
    "",
