      var b = sceneWaterCreateStateTarget(gl, resolution, formats[fi].internal, formats[fi].type, filter);
      if (!b) { gl.deleteTexture(a.tex); gl.deleteFramebuffer(a.fbo); continue; }
      states = [a, b];
