      programs = {};
      if (states) {
        gl.deleteTexture(states[0].tex); gl.deleteFramebuffer(states[0].fbo);
        gl.deleteTexture(states[1].tex); gl.deleteFramebuffer(states[1].fbo);
        states = null;
      }
